import { overallVerdict } from "@/lib/data";

interface VerdictMeterProps {
  nameA: string;
  nameB: string;
  menang: number;
  seri: number;
  kalah: number;
  total: number;
  scoreA: number;
  scoreB: number;
}

export default function VerdictMeter({
  nameA,
  nameB,
  menang,
  seri,
  kalah,
  total,
  scoreA,
  scoreB,
}: VerdictMeterProps) {
  // Pemenang overall ikut skor total — tidak pernah kontradiksi headline.
  const overall = overallVerdict(nameA, nameB, scoreA, scoreB);
  const seimbang = overall.pemenang === "Seimbang";

  // Posisi penanda pada skala 0-100: 0 = A telak, 50 = seimbang, 100 = B telak.
  const diff = scoreA - scoreB;
  const markerPct = Math.min(98, Math.max(2, 50 - (diff / 20) * 50));

  // Rincian spek apa adanya (boleh berbeda arah dengan pemenang overall).
  const specLead =
    menang === kalah
      ? `imbang ${menang}-${kalah}`
      : menang > kalah
        ? `${nameA} ${menang}-${kalah}`
        : `${nameB} ${kalah}-${menang}`;

  const title = seimbang ? "Hasil Seimbang" : `${overall.pemenang} Menang ${overall.label}`;

  return (
    <div
      style={{
        background: seimbang ? "#f0fdf4" : "#eff6ff",
        border: `1px solid ${seimbang ? "#bbf7d0" : "#bfdbfe"}`,
        borderRadius: 12,
        padding: "14px 16px",
        marginBottom: 16,
      }}
    >
      <div
        style={{ fontWeight: 800, fontSize: 12, color: "#0f172a", marginBottom: 4 }}
      >
        ★ Verdict Pilihan — {title}
      </div>

      {/* Skala range kesimpulan berdasar selisih skor total */}
      <div style={{ marginTop: 10, marginBottom: 4 }}>
        <div
          style={{
            position: "relative",
            height: 8,
            borderRadius: 4,
            background:
              "linear-gradient(90deg, #2563eb 0%, #93c5fd 35%, #e2e8f0 50%, #93c5fd 65%, #1d4ed8 100%)",
          }}
        >
          {/* garis tengah = seimbang */}
          <span
            style={{
              position: "absolute",
              left: "50%",
              top: -3,
              bottom: -3,
              width: 2,
              background: "#0f172a",
              borderRadius: 1,
              transform: "translateX(-50%)",
            }}
          />
          {/* penanda hasil */}
          <span
            title={title}
            style={{
              position: "absolute",
              left: `${markerPct}%`,
              top: "50%",
              width: 16,
              height: 16,
              borderRadius: "50%",
              background: "#fff",
              border: "3px solid #0f172a",
              transform: "translate(-50%, -50%)",
            }}
          />
        </div>
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            fontSize: 9,
            fontWeight: 800,
            color: "#64748b",
            marginTop: 4,
          }}
        >
          <span>{nameA} telak</span>
          <span>Seimbang</span>
          <span>{nameB} telak</span>
        </div>
      </div>

      <div style={{ fontSize: 13, lineHeight: 1.6, color: "#334155" }}>
        {overall.message} Per spek: {specLead}
        {total > 0 && ` dari ${total} spesifikasi (${seri} seri)`}.
      </div>

      {!seimbang && (
        <div
          style={{
            marginTop: 8,
            fontSize: 12,
            fontWeight: 800,
            color: "#1d4ed8",
          }}
        >
          Pilih {overall.pemenang} jika Anda ingin hasil terbaik secara umum.
        </div>
      )}
    </div>
  );
}
