"use client";

import { useMemo, useState, type FormEvent } from "react";
import { useRouter, useSearchParams } from "next/navigation";
import Link from "next/link";
import {
  categoryIds,
  categoriesMeta,
  learnItems,
  type CategoryId,
  type Comparison,
  type Product,
} from "@/lib/data";
import ProductCard from "./ProductCard";
import ComparePicker from "./ComparePicker";
import DynamicComparison from "./DynamicComparison";
import CompareCard from "./CompareCard";

export default function CompareStudio({
  allProducts,
  popular,
}: {
  allProducts: Product[];
  popular: Comparison[];
}) {
  const router = useRouter();
  const params = useSearchParams();
  const [draft, setDraft] = useState(params.get("q") ?? "");

  const q = params.get("q") ?? "";
  const cat = params.get("category") ?? "";
  const idA = params.get("a") ?? "";
  const idB = params.get("b") ?? "";

  const setParams = (patch: Record<string, string | null>) => {
    const next = new URLSearchParams(params.toString());
    for (const [k, v] of Object.entries(patch)) {
      if (v === null || v === "") next.delete(k);
      else next.set(k, v);
    }
    router.push(`/compare?${next.toString()}`);
  };

  const submitSearch = (e: FormEvent) => {
    e.preventDefault();
    setParams({ q: draft.trim() || null });
  };

  const pick = (id: string, slot: "a" | "b") => {
    if (slot === "a") {
      setParams({ a: idA === id ? null : id });
    } else {
      setParams({ b: idB === id ? null : id });
    }
  };

  const visible = useMemo(() => {
    const keyword = q.trim().toLowerCase();
    return allProducts.filter((p) => {
      if (cat && p.category !== cat) return false;
      if (!keyword) return true;
      return (
        p.keywords.includes(keyword) ||
        p.name.toLowerCase().includes(keyword) ||
        p.brand.toLowerCase().includes(keyword)
      );
    });
  }, [allProducts, q, cat]);

  const matchedLearn = useMemo(() => {
    const keyword = q.trim().toLowerCase();
    if (!keyword) return [];
    return learnItems.filter(
      (l) =>
        l.title.toLowerCase().includes(keyword) ||
        l.desc.toLowerCase().includes(keyword),
    );
  }, [q]);

  const productA = allProducts.find((p) => p.id === idA);
  const productB = allProducts.find((p) => p.id === idB);
  const liveReady =
    !!productA &&
    !!productB &&
    productA.id !== productB.id &&
    productA.category === productB.category;

  return (
    <div>
      <ComparePicker
        productA={productA}
        productB={productB}
        onSwap={() => setParams({ a: idB || null, b: idA || null })}
        onClear={() => setParams({ a: null, b: null })}
      />

      {liveReady && (
        <div
          style={{
            background: "linear-gradient(135deg, #f8fbff, #fff)",
            border: "1px solid #cfe0ff",
            borderRadius: 12,
            padding: 18,
            marginBottom: 20,
          }}
        >
          <h2
            style={{
              fontSize: 16,
              margin: "0 0 12px",
              fontFamily: "var(--font-manrope), Manrope, sans-serif",
            }}
          >
            Hasil Cepat: {productA!.name} vs {productB!.name}
          </h2>
          <DynamicComparison productA={productA!} productB={productB!} />
          <Link
            href={`/compare/custom?a=${productA!.id}&b=${productB!.id}`}
            className="view-all"
            style={{ display: "inline-block", marginTop: 12 }}
          >
            Buka halaman penuh →
          </Link>
        </div>
      )}

      <form className="search-box" onSubmit={submitSearch} style={{ marginBottom: 12 }}>
        <span className="search-icon">⌕</span>
        <input
          type="search"
          autoComplete="off"
          placeholder="Cari barang satuan... (misal iphone, thinkpad, nike)"
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
        />
        <button type="submit">→</button>
      </form>

      <div className="pills" style={{ marginTop: 0, marginBottom: 8 }}>
        <button
          type="button"
          onClick={() => setParams({ category: null })}
          style={
            !cat
              ? { background: "#2563eb", color: "#fff", borderColor: "#2563eb" }
              : undefined
          }
        >
          All ({allProducts.length})
        </button>
        {categoryIds.map((id: CategoryId) => (
          <button
            key={id}
            type="button"
            onClick={() => setParams({ category: cat === id ? null : id })}
            style={
              cat === id
                ? { background: "#2563eb", color: "#fff", borderColor: "#2563eb" }
                : undefined
            }
          >
            {categoriesMeta[id].icon} {categoriesMeta[id].name}
          </button>
        ))}
      </div>

      {matchedLearn.length > 0 && (
        <div
          style={{
            background: "#eff6ff",
            border: "1px solid #bfdbfe",
            borderRadius: 12,
            padding: "12px 14px",
            margin: "10px 0 14px",
          }}
        >
          <div style={{ fontSize: 11, fontWeight: 800, color: "#1e40af", marginBottom: 8 }}>
            📘 Materi terkait “{q.trim()}”
          </div>
          <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
            {matchedLearn.map((l) => (
              <Link
                key={l.slug}
                href={`/learn/${l.slug}`}
                style={{
                  background: "#fff",
                  border: "1px solid #dbeafe",
                  borderRadius: 10,
                  padding: "8px 12px",
                  fontSize: 11,
                  fontWeight: 800,
                  color: "#1d4ed8",
                  textDecoration: "none",
                }}
              >
                {l.icon} {l.title} →
              </Link>
            ))}
          </div>
        </div>
      )}

      <p style={{ fontSize: 11, color: "#64748b", margin: "10px 0 14px" }}>
        Pilih 2 barang satuan (HP×HP, laptop×laptop, sepatu×sepatu, merek
        bebas), lalu klik Bandingkan. Menampilkan {visible.length} dari{" "}
        {allProducts.length} barang.
      </p>

      {visible.length === 0 ? (
        <div
          style={{
            background: "#fff",
            border: "1px solid #e2e8f0",
            borderRadius: 12,
            padding: 32,
            textAlign: "center",
            color: "#64748b",
            fontSize: 13,
          }}
        >
          Tidak ada barang yang cocok. Coba kata kunci lain.
        </div>
      ) : (
        <div className="comparison-grid">
          {visible.map((p) => (
            <ProductCard
              key={p.id}
              product={p}
              slotA={idA === p.id}
              slotB={idB === p.id}
              onPickA={() => pick(p.id, "a")}
              onPickB={() => pick(p.id, "b")}
            />
          ))}
        </div>
      )}

      <div style={{ marginTop: 32 }}>
        <div className="section-head">
          <div>
            <h2>Popular Comparisons</h2>
            <p>Perbandingan curated pilihan editor.</p>
          </div>
        </div>
        <div className="comparison-grid">
          {popular.map((c) => (
            <CompareCard key={c.slug} comparison={c} />
          ))}
        </div>
      </div>
    </div>
  );
}
