"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import type { CSSProperties } from "react";
import type { SpecRow } from "@/lib/data";
import { specGlossary, specVerdict, getLearnItem } from "@/lib/data";

interface SpecTableProps {
  specs: SpecRow[];
  nameA: string;
  nameB: string;
}

function getLearnSlugs(label: string): string[] {
  return specGlossary[label]?.learnSlugs ?? [];
}

function learnTitle(slug: string): string {
  return getLearnItem(slug)?.title ?? slug;
}

export default function SpecTable({
  specs,
  nameA,
  nameB,
}: SpecTableProps) {
  const [openIndex, setOpenIndex] = useState<number | null>(null);

  const toggle = (index: number) => setOpenIndex((prev) => (prev === index ? null : index));

  const router = useRouter();

  // Hitung verdict
  let menang = 0,
    seri = 0,
    kalah = 0;
  for (const s of specs) {
    const scoreA = s.scoreA ?? 0;
    const scoreB = s.scoreB ?? 0;
    if (Math.abs(scoreA - scoreB) <= 2) seri++;
    else if (scoreA > scoreB) menang++;
    else kalah++;
  }

  return (
    <div
      style={{
        background: "#fff",
        border: "1px solid #e2e8f0",
        borderRadius: 12,
        overflow: "hidden",
      }}
    >
      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr 1fr 34px",
          gap: 8,
          padding: "12px 16px",
          background: "#f8fafc",
          fontSize: 10,
          fontWeight: 800,
          color: "#475569",
          textTransform: "uppercase",
          letterSpacing: "0.08em",
        }}
      >
        <span>Spesifikasi</span>
        <span>{nameA}</span>
        <span>{nameB}</span>
        <span style={{ textAlign: "center" }}>Ver</span>
      </div>
      {specs.map((s, i) => {
        const scoreA = s.scoreA ?? 0;
        const scoreB = s.scoreB ?? 0;
        const verdict = specVerdict(scoreA, scoreB);
        const aText = s.a ?? "-";
        const bText = s.b ?? "-";
        const aScore = scoreA > 0 ? scoreA : null;
        const bScore = scoreB > 0 ? scoreB : null;

        // Tentukan label spesifikasi untuk lookup glossary
        const labelKey = s.label;
        const isLearnable =
          labelKey === "Layar" ||
          labelKey === "Cushioning" ||
          labelKey === "Kamera utama" ||
          labelKey === "Software" ||
          labelKey === "Chipset" ||
          labelKey === "Kamera zoom" ||
          labelKey === "Ketahanan" ||
          labelKey === "Baterai";

        return (
          <div
            key={s.label}
            style={{
              display: "grid",
              gridTemplateColumns: "1fr 1fr 1fr 34px",
              gap: 8,
              padding: "12px 16px",
              borderTop: "1px solid #f1f5f9",
              fontSize: 12,
              background: "#f8fafc",
            }}
          >
<div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 4,
              }}
            >
              <b
                style={{
                  color: "#0f172a",
                  fontWeight: 800,
                  width: 100,
                  fontSize: 11,
                }}
              >
                {s.label}
                {openIndex === i && (
                  <span
                    style={{
                      cursor: "pointer",
                      fontSize: 9,
                      color: "#2563eb",
                      fontWeight: 700,
                    }}
                    onClick={() => toggle(i)}
                  >
                    ⓘ
                  </span>
                )}
              </b>
              {openIndex === i && (
                <div
                  style={{
                    marginTop: 6,
                    maxHeight: 80,
                    overflow: "hidden",
                    fontSize: 11,
                    color: "#475569",
                    lineHeight: 1.5,
                  }}
                >
                  {isLearnable && getLearnSlugs(labelKey).length > 0 && (
                    <div
                      style={{
                        marginBottom: 4,
                        display: "flex",
                        gap: 8,
                        flexWrap: "wrap",
                      }}
                    >
                      {getLearnSlugs(labelKey).map((slug) => (
                        <span
                          key={slug}
                          style={{
                            cursor: "pointer",
                            color: "#2563eb",
                            fontWeight: 700,
                            fontSize: 10,
                          }}
                          onClick={() => router.push(`/learn/${slug}`)}
                        >
                          → Pelajari {learnTitle(slug)}
                        </span>
                      ))}
                    </div>
                  )}
                  <span>{specGlossary[labelKey]?.simple ?? ""}</span>
                </div>
              )}
            </div>
            <span
              style={{
                color: "#334155",
                fontWeight: 700,
                fontSize: 11,
                textAlign: "center",
                minWidth: 80,
                display: "block",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 4,
                }}
              >
                <span>{aText}</span>
                {aScore !== null && (
                  <small
                    style={{
                      color: "#2563eb",
                      fontWeight: 800,
                      fontSize: 9,
                      minWidth: 28,
                    }}
                  >
                    {aScore}
                  </small>
                )}
                <i
                  style={{
                    "--score": `${scoreA}%`,
                    display: "block",
                    height: 4,
                    borderRadius: 2,
                    background: "linear-gradient(90deg, #2563eb var(--score), #e2e8f0 var(--score))",
                    width: 60,
                  } as CSSProperties}
                />
              </div>
            </span>
            <span
              style={{
                color: "#334155",
                fontWeight: 700,
                fontSize: 11,
                textAlign: "center",
                minWidth: 80,
                display: "block",
              }}
            >
              <div
                style={{
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  gap: 4,
                }}
              >
                <span>{bText}</span>
                {bScore !== null && (
                  <small
                    style={{
                      color: "#2563eb",
                      fontWeight: 800,
                      fontSize: 9,
                      minWidth: 28,
                    }}
                  >
                    {bScore}
                  </small>
                )}
                <i
                  style={{
                    "--score": `${scoreB}%`,
                    display: "block",
                    height: 4,
                    borderRadius: 2,
                    background: "linear-gradient(90deg, #2563eb var(--score), #e2e8f0 var(--score))",
                    width: 60,
                  } as CSSProperties}
                />
              </div>
            </span>
            <span
              style={{
                color: "#334155",
                fontWeight: 800,
                fontSize: 9,
                textAlign: "center",
                minWidth: 34,
                background:
                  verdict === "A"
                    ? "#dbeafe"
                    : verdict === "B"
                      ? "#eff6ff"
                      : "#f0fdf4",
                borderRadius: 6,
                padding: "2px 6px",
                marginLeft: 4,
              }}
            >
              {verdict}
            </span>
          </div>
        );
      })}

      {/* Baris verdict singkat di bawah */}
      <div
        style={{
          padding: "10px 14px",
          background: "#f8fafc",
          borderTop: "1px solid #e2e8f0",
          fontSize: 11,
          color: "#334155",
        }}
      >
        <b>Verdict:</b> {nameA} menang {menang} dari {specs.length} spek {seri} seri {kalah} kalah{" "}
        {menang > kalah ? `→ Pilih ${nameA}` : kalah > menang ? `→ Pilih ${nameB}` : "→ Seimbang"}
      </div>
    </div>
  );
}