import Link from "next/link";
import type { Comparison } from "@/lib/data";
import ScoreBar from "./ScoreBar";

export default function CompareCard({ comparison }: { comparison: Comparison }) {
  const [a, b] = comparison.products;
  return (
    <Link
      href={`/compare/${comparison.slug}`}
      aria-label={`Bandingkan ${a.name} vs ${b.name}`}
      style={{ textDecoration: "none", color: "inherit", display: "block" }}
    >
      <article className="compare-card">
        <div className="versus-row">
          <div className="compare-product">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img className="compare-product-img" src={a.img} alt={a.name} />
            <b>{a.name}</b>
            <small>{a.brand}</small>
          </div>
          <span className="vs">VS</span>
          <div className="compare-product">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img className="compare-product-img" src={b.img} alt={b.name} />
            <b>{b.name}</b>
            <small>{b.brand}</small>
          </div>
        </div>
        <div className="scores">
          <ScoreBar score={a.score} label={`${a.score}/100`} />
          <ScoreBar score={b.score} label={`${b.score}/100`} />
        </div>
        <span className="card-link">View Comparison →</span>
      </article>
    </Link>
  );
}
